texts.en:
Thank you for booking with {business}.

Booking #{id}: {service}
Date: {date}
Arrival window: {slot}
Address: {address}
Total: {total} ({payment})

Follow, change or cancel your booking: {link}

texts.ar:
شكراً لحجزك مع {business}.

الحجز رقم {id}: {service}
التاريخ: {date}
موعد الوصول: {slot}
العنوان: {address}
الإجمالي: {total} ({payment})

لمتابعة حجزك أو تعديله أو إلغائه: {link}

texts.en:
A reminder of booking #{id} with {business} tomorrow, {date}.
Arrival window: {slot}
Address: {address}
Total: {total} ({payment})

Follow or cancel it: {link}

texts.ar:
تذكير بالحجز رقم {id} مع {business} غداً، {date}.
موعد الوصول: {slot}
العنوان: {address}
الإجمالي: {total} ({payment})

لمتابعته أو إلغائه: {link}

texts.en:
We booked your next visit with {business} (booking #{id}): {service} on {date}.
Arrival window: {slot}
Address: {address}
Total: {total}

Pay the crew on completion, or pay by card here: {link}
Not convenient? Open the same link to cancel this visit or stop the repeats.

texts.ar:
حجزنا زيارتك القادمة مع {business} (الحجز رقم {id}): {service} يوم {date}.
موعد الوصول: {slot}
العنوان: {address}
الإجمالي: {total}

ادفع للفريق عند الانتهاء، أو ادفع بالبطاقة من هنا: {link}
الموعد غير مناسب؟ افتح الرابط نفسه لإلغاء هذه الزيارة أو إيقاف التكرار.

texts.en:
Good news: {crew} and team from {business} will do your {service} on {date}.
Arrival window: {slot}
Address: {address}

Follow your crew live on the day: {link}

texts.ar:
خبر سار: {crew} وفريقه من {business} سيقومون بخدمة {service} يوم {date}.
موعد الوصول: {slot}
العنوان: {address}

تابع فريقك مباشرة يوم الزيارة: {link}

texts.en:
We are sorry: {business} had to cancel booking #{id} ({service} on {date}, arrival {slot}).
{refund}
Reply to this email or book another time: {link}

texts.ar:
نعتذر: اضطرت {business} إلى إلغاء الحجز رقم {id} ({service} يوم {date}، الوصول {slot}).
{refund}
رد على هذه الرسالة أو احجز موعداً آخر: {link}

texts.en:
We booked your next visit with {business} (booking #{id}): {service} on {date}.
Arrival window: {slot}
Address: {address}
Total: {total} ({payment})

Your card is charged automatically: nothing to pay the crew.
Not convenient? Cancel this visit or stop the repeats here: {link}

texts.ar:
حجزنا زيارتك القادمة مع {business} (الحجز رقم {id}): {service} يوم {date}.
موعد الوصول: {slot}
العنوان: {address}
الإجمالي: {total} ({payment})

تُخصم القيمة من بطاقتك تلقائياً، فلا تدفع شيئاً للفريق.
الموعد غير مناسب؟ ألغِ هذه الزيارة أو أوقف التكرار من هنا: {link}

texts.en:
The automatic card payment of {total} for your visit with {business} (booking #{id}: {service} on {date}, arrival {slot}) did not go through.

Pay by card here: {link}
or pay the crew on completion. Not convenient? Open the same link to cancel this visit or stop the repeats.

texts.ar:
لم ينجح الخصم التلقائي بقيمة {total} لزيارتك مع {business} (الحجز رقم {id}: {service} يوم {date}، الوصول {slot}).

ادفع بالبطاقة من هنا: {link}
أو ادفع للفريق عند الانتهاء. الموعد غير مناسب؟ افتح الرابط نفسه لإلغاء هذه الزيارة أو إيقاف التكرار.

templates.home:
{{template "top" .}}{{if .theme.lux}}<section class="hero{{if .biz.hero_image}} has-photo{{end}}">{{with .biz.hero_image}}<img class="hero-img" src="{{.}}?w=1600" srcset="{{.}}?w=800 800w, {{.}}?w=1200 1200w, {{.}}?w=1600 1600w, {{.}}?w=2000 2000w" sizes="100vw" alt="" fetchpriority="high">{{end}}
<div class="hero-text"><h1>{{if .tagline}}{{.tagline}}{{else}}{{.storeName}}{{end}}</h1>{{if .categories}}<a class="cta" href="#services">{{.t.choose_service}}</a>{{end}}</div></section>
{{with .story}}<section class="story"><div class="wrap"><p>{{.}}</p></div></section>{{end}}
{{else}}<section class="intro{{if .biz.hero_image}} has-photo{{end}}"><div class="wrap"><div class="intro-text"><h1>{{if .tagline}}{{.tagline}}{{else}}{{.storeName}}{{end}}</h1>{{if .categories}}<a class="btn on-brand" href="#services">{{.t.choose_service}}</a>{{end}}</div>{{with .biz.hero_image}}<div class="intro-photo"><img src="{{.}}?w=960" srcset="{{.}}?w=480 480w, {{.}}?w=960 960w, {{.}}?w=1400 1400w" sizes="(min-width:720px) 45vw, 100vw" alt="" fetchpriority="high"></div>{{end}}</div></section>{{end}}
<section class="collection svc" id="services" aria-labelledby="svc-h"><div class="wrap"><h2 id="svc-h">{{.t.services}}</h2>
{{if gt (len .categories) 1}}<nav class="cats" aria-label="{{.t.categories}}"><a href="/{{.qs}}#services"{{if not .category}} aria-current="page"{{end}}>{{.t.all}}</a>{{range .categories}}<a href="/?c={{.value}}{{$.amp}}#services"{{if eq .value $.category}} aria-current="page"{{end}}>{{.label}}</a>{{end}}</nav>{{end}}
{{if .services}}<div class="tiles">{{range .services}}<a class="tile" href="/s/{{.id}}{{$.qs}}"><span class="well">{{if .image}}<img src="{{.image}}?w=640" srcset="{{.image}}?w=480 480w, {{.image}}?w=640 640w, {{.image}}?w=960 960w" sizes="(min-width:1080px) 33vw, 50vw" alt="" loading="lazy">{{else}}<span class="small">{{.name}}</span>{{end}}</span>
<span class="tname">{{.name}}</span><span class="per-line"><span class="price">{{.priceText}}</span> <span class="per">{{.perText}}</span></span></a>{{end}}</div>
{{else}}<div class="empty"><h2>{{.t.no_services}}</h2><p>{{.t.no_services_hint}}</p>{{if .wa}}<a class="btn" href="https://wa.me/{{.wa}}" target="_blank" rel="noopener">{{.t.contact_whatsapp}}</a>{{end}}</div>{{end}}</div></section>
{{if not .theme.lux}}{{if or .story .biz.story_image}}<section class="about{{if .biz.story_image}} has-photo{{end}}"><div class="wrap">{{with .biz.story_image}}<div class="about-img"><img src="{{.}}?w=960" srcset="{{.}}?w=640 640w, {{.}}?w=960 960w" sizes="(min-width:720px) 40vw, 100vw" alt="" loading="lazy"></div>{{end}}
<div class="about-text"><h2>{{.t.about_title}}</h2>{{with .story}}<p>{{.}}</p>{{end}}{{if .wa}}<a class="btn line" href="https://wa.me/{{.wa}}" target="_blank" rel="noopener">{{.t.contact_whatsapp}}</a>{{end}}</div></div></section>{{end}}{{end}}
<section class="know" aria-labelledby="know-h"><div class="wrap"><h2 id="know-h">{{.t.good_to_know}}</h2>
<dl class="facts"><div><dt>{{.t.areas}}</dt><dd><ul class="zones">{{range .zones}}<li><span>{{.name}}</span>{{if .surcharge}}<span class="price">+ {{.surcharge}}</span>{{end}}</li>{{end}}</ul></dd></div>
<div><dt>{{.t.fact_visits}}</dt><dd>{{.hoursNote}}</dd></div>
<div><dt>{{.t.payment}}</dt><dd>{{if .card}}<span>{{.t.pay_card}}</span>{{end}}{{if .cash}}<span>{{.t.pay_cash}}</span>{{end}}<span>{{.t.vat_included}}</span></dd></div>
<div><dt>{{.t.fact_cancel}}</dt><dd>{{.cancelNote}}</dd></div></dl></div></section>
{{if .theme.lux}}{{with .biz.story_image}}<section class="visit"><div class="visit-img"><img src="{{.}}?w=960" srcset="{{.}}?w=640 640w, {{.}}?w=960 960w" sizes="(min-width:900px) 50vw, 100vw" alt="" loading="lazy"></div>
<div class="visit-text"><h2>{{$.t.visit_title}}</h2>{{with $.address}}<p>{{.}}</p>{{end}}{{if $.wa}}<a class="cta" href="https://wa.me/{{$.wa}}" target="_blank" rel="noopener">{{$.t.contact_whatsapp}}</a>{{end}}</div></section>{{end}}{{end}}
{{template "bottom" .}}

templates.service:
{{template "top" .}}{{with .svc}}<div class="wrap pdp">
<div class="pdp-media"><div class="well">{{if .image}}<img src="{{.image}}?w=960" srcset="{{.image}}?w=640 640w, {{.image}}?w=960 960w, {{.image}}?w=1200 1200w" sizes="(min-width: 900px) 58vw, 100vw" alt="{{.name}}">{{else}}<span>{{.name}}</span>{{end}}</div></div>
<div class="pdp-info"><h1>{{.name}}</h1><p class="pprice"><span class="price">{{.priceText}}</span> <span class="per">{{.perText}}</span></p><p class="small quiet">{{$.t.vat_included}}</p>
{{with .description}}<p class="desc">{{.}}</p>{{end}}
<form class="book" id="book" method="get" action="/checkout">{{with $.error}}<p class="alert" role="alert">{{.}}</p>{{end}}
<input type="hidden" name="service" value="{{.id}}">{{if eq $.lang "ar"}}<input type="hidden" name="lang" value="ar">{{end}}
{{if .fixed}}<input type="hidden" name="qty" id="qty" value="1">{{else}}<div class="field qtyfield"><span class="lab" id="qty-label">{{$.t.how_many}}</span><div class="stepper"><button type="button" data-step="-1" aria-label="{{$.t.qty_less}}">−</button><input id="qty" name="qty" type="number" inputmode="numeric" min="{{.min}}" max="{{.max}}" value="{{.min}}" required aria-labelledby="qty-label" aria-describedby="qty-hint"><button type="button" data-step="1" aria-label="{{$.t.qty_more}}">+</button></div><span class="hint" id="qty-hint">{{$.qtyHint}}</span></div>{{end}}
{{if .materials}}<label class="choice extra"><input type="checkbox" name="materials" id="materials" value="1"><span>{{$.t.materials}}<span class="hint">+ {{.materialsText}}</span></span></label>{{end}}
<div class="where"><div class="field"><label for="zone">{{$.t.area}}</label><select id="zone" name="zone" required>{{range $.zones}}<option value="{{.id}}" data-surcharge="{{.surchargeNum}}">{{.name}}{{if .surcharge}} (+ {{.surchargeShort}}){{end}}</option>{{end}}</select></div>
<div class="field"><label for="date">{{$.t.date}}</label><select id="date" name="date" required>{{range $.dates}}<option value="{{.value}}">{{.label}}</option>{{end}}</select></div></div>
<fieldset class="opts"><legend>{{$.t.arrival}}</legend><div id="slots" class="opt-list slots" aria-live="polite"></div><p class="hint" id="noslots" hidden>{{$.t.no_slots}}</p></fieldset>
<fieldset class="opts"><legend>{{$.t.repeat}}</legend><div class="opt-list"><label class="opt"><input type="radio" name="repeat" value="once" checked><span>{{$.t.repeat_once}}</span></label><label class="opt"><input type="radio" name="repeat" value="weekly"><span>{{$.t.repeat_weekly}}</span></label><label class="opt"><input type="radio" name="repeat" value="every_2_weeks"><span>{{$.t.repeat_every_2_weeks}}</span></label></div>
<p class="hint" id="repeat-note" hidden>{{$.t.repeat_note}}</p></fieldset>
<div class="rows quote"><div class="row"><span>{{.name}}</span><span id="p-service"></span></div><div class="row" id="r-mat" hidden><span>{{$.t.materials}}</span><span id="p-mat"></span></div>
<div class="row" id="r-zone" hidden><span>{{$.t.area_fee}}</span><span id="p-zone"></span></div><div class="row total"><span>{{$.t.total}}</span><span id="p-total"></span></div>
<div class="row sub"><span>{{$.t.vat_amount}}</span><span id="p-vat"></span></div></div>
<div class="buybar"><span class="buybar-price price" id="bar-total" aria-hidden="true"></span><button class="btn" id="go" disabled>{{$.t.continue}}</button></div>
<p class="hint pick-hint" id="pick-hint">{{$.t.pick_window}}</p></form>
<dl class="facts"><div><dt>{{$.t.fact_window}}</dt><dd>{{$.t.fact_window_text}}</dd></div><div><dt>{{$.t.fact_cancel}}</dt><dd>{{$.cancelNote}}</dd></div>
<div><dt>{{$.t.payment}}</dt><dd>{{if $.card}}<span>{{$.t.pay_card}}</span>{{end}}{{if $.cash}}<span>{{$.t.pay_cash}}</span>{{end}}</dd></div></dl>
</div></div>{{end}}
<script>
(function(){var S={{.calc}},MF={{.t.money}},FULL={{.t.slot_full}};
function el(i){return document.getElementById(i)}
function fmt(n){return MF.replace('{n}',(Math.round(n*100)/100).toFixed(2))}
document.body.classList.add('has-buybar');
function qty(){return S.fixed?1:Math.max(S.min,Math.min(S.max,Math.floor(Number(el('qty').value)||S.min)))}
function clamp(){if(S.fixed)return;var q=qty();el('qty').value=q;document.querySelector('[data-step="-1"]').disabled=q<=S.min;document.querySelector('[data-step="1"]').disabled=q>=S.max}
function repeat(){var r=document.querySelector('input[name=repeat]:checked');return r?r.value:'once'}
// A price for display only: the server works the booking out again from its own prices.
function sum(){var q=qty(),m=el('materials')&&el('materials').checked?S.materials*(S.hourly?q:1):0,o=el('zone').options[el('zone').selectedIndex],z=o?Number(o.dataset.surcharge)||0:0,t=S.price*q+m+z;
 el('p-service').textContent=fmt(S.price*q);el('r-mat').hidden=!m;el('p-mat').textContent=fmt(m);el('r-zone').hidden=!z;el('p-zone').textContent=fmt(z);
 el('p-total').textContent=fmt(t);el('bar-total').textContent=fmt(t);el('p-vat').textContent=fmt(t*5/105);el('repeat-note').hidden=repeat()==='once'}
function ready(on){el('go').disabled=!on;el('pick-hint').hidden=on}
function slots(){var box=el('slots');box.textContent='';ready(false);if(!el('date').value){el('noslots').hidden=false;return}
 fetch('/api/slots?date='+encodeURIComponent(el('date').value)).then(function(r){return r.json()}).then(function(d){var any=false;
  d.slots.forEach(function(s){var l=document.createElement('label'),i=document.createElement('input'),sp=document.createElement('span');
   l.className='opt';i.type='radio';i.name='slot';i.value=s.start;i.required=true;i.disabled=!s.left;i.onchange=function(){ready(true)};
   sp.textContent=s.start+'–'+s.end;l.appendChild(i);l.appendChild(sp);
   if(!s.left){var f=document.createElement('span');f.className='small';f.textContent=FULL;l.appendChild(f)}else any=true;box.appendChild(l)});
  el('noslots').hidden=any})}
document.querySelectorAll('[data-step]').forEach(function(b){b.addEventListener('click',function(){el('qty').value=qty()+Number(b.dataset.step);clamp();sum()})});
if(el('qty')&&!S.fixed)el('qty').addEventListener('change',function(){clamp();sum()});
['materials','zone'].forEach(function(i){if(el(i))el(i).addEventListener('change',sum)});
document.querySelectorAll('input[name=repeat]').forEach(function(r){r.addEventListener('change',sum)});
el('date').addEventListener('change',slots);clamp();sum();slots();
})();
</script>{{template "bottom" .}}

templates.checkout:
{{template "top" .}}<div class="wrap"><div class="page-head"><h1>{{.t.checkout}}</h1></div>{{with .error}}<p class="alert" role="alert">{{.}}</p>{{end}}
<div class="co">{{with .sel}}<aside class="co-side"><div class="sheet"><h2>{{$.t.your_visit}}</h2><p class="visit-name">{{.service}}</p>
<dl class="facts plain"><div><dt>{{$.t.when}}</dt><dd><time datetime="{{.date}}">{{.dateText}}</time><span>{{$.t.arrival}} <span class="num">{{.slot}}–{{.slotEnd}}</span></span></dd></div>
<div><dt>{{$.t.area}}</dt><dd>{{.zone}}</dd></div>{{with .repeatText}}<div><dt>{{$.t.repeat}}</dt><dd>{{.}}</dd></div>{{end}}</dl>
<div class="rows">{{range .lines}}<div class="row"><span>{{.name}} × {{.qty}}</span><span>{{.amount}}</span></div>{{end}}
{{with .surcharge}}<div class="row"><span>{{$.t.area_fee}}</span><span>{{.}}</span></div>{{end}}
<div class="row total"><span>{{$.t.total}}</span><span>{{.total}}</span></div><div class="row sub"><span>{{$.t.vat_amount}}</span><span>{{.vat}}</span></div></div>
<p class="small" style="margin-top:12px"><a href="/s/{{.serviceId}}{{$.qs}}">{{$.t.change}}</a></p></div></aside>{{end}}
<form class="co-main" method="post" action="/book">{{range .hidden}}<input type="hidden" name="{{.name}}" value="{{.value}}">{{end}}
<fieldset class="group"><legend>{{.t.contact_details}}</legend><div class="pair">
<div class="field"><label for="name">{{.t.name}}</label><input id="name" name="name" required autocomplete="name" value="{{.user.name}}"></div>
<div class="field"><label for="phone">{{.t.phone}}</label><input id="phone" name="phone" type="tel" required autocomplete="tel" value="{{.user.phone}}" placeholder="+971 50 123 4567" dir="ltr"></div></div></fieldset>
<fieldset class="group"><legend>{{.t.address_details}}</legend>
<div class="field"><label for="address">{{.t.address}}</label><input id="address" name="address" required autocomplete="street-address" aria-describedby="address-hint"><span class="hint" id="address-hint">{{.t.address_hint}}</span></div>
<div class="field"><label for="flat">{{.t.flat}}</label><input id="flat" name="flat"></div>
<div class="field"><label for="notes">{{.t.notes}}</label><textarea id="notes" name="notes" rows="2" maxlength="500" aria-describedby="notes-hint"></textarea><span class="hint" id="notes-hint">{{.t.notes_hint}}</span></div>
<div class="field"><label for="photo">{{.t.photo}}</label><input id="photo" type="file" name="photo" data-rx-upload accept="image/*" aria-describedby="photo-hint"><span class="hint" id="photo-hint">{{.t.photo_hint}}</span></div></fieldset>
<fieldset class="group"><legend>{{.t.payment}}</legend>
{{if .card}}<label class="choice"><input type="radio" name="payment" value="card" checked><span>{{.t.pay_card}}<span class="hint">{{.t.pay_card_hint}}</span></span></label>{{end}}
{{if .auto}}<label class="choice"><input type="radio" name="payment" value="auto"><span>{{.autoText}}<span class="hint">{{.t.pay_auto_hint}}</span></span></label>{{end}}
{{if .cash}}<label class="choice"><input type="radio" name="payment" value="cash"{{if not .card}} checked{{end}}><span>{{.t.pay_cash}}<span class="hint">{{.t.pay_cash_hint}}</span></span></label>{{end}}</fieldset>
<button class="btn wide">{{.t.book_now}}</button></form></div></div><script src="/_rx/upload.js"></script>{{template "bottom" .}}

templates.booking:
{{template "top" .}}{{with .bk}}<div class="wrap">{{if $.placed}}<div class="notice" role="status" style="margin-top:24px"><p><strong>{{$.t.thank_you}}</strong></p><p>{{$.t.thank_you_hint}}</p></div>{{end}}
<div class="page-head"><h1>{{.title}}</h1><p class="visit-line"><span>{{.service}}</span><span><time datetime="{{.date}}">{{.dateText}}</time> <span class="num">{{.slot}}–{{.slotEnd}}</span></span></p>
<p class="state{{if .steps}} sr{{end}}">{{$.t.status}}: <strong class="status{{if .bad}} bad{{end}}" id="status">{{.statusText}}</strong></p>
{{if .canPay}}<form method="post" action="/bookings/{{.id}}/pay{{$.qs}}" class="actions noprint"><button class="btn{{if ne .status "pending"}} line{{end}}">{{$.t.pay_now}}</button></form>{{end}}</div>
{{with .steps}}<section class="tracker" aria-labelledby="track-h"><h2 id="track-h" class="sr">{{$.t.track_title}}</h2><ol class="track" id="steps">{{range .}}<li data-s="{{.key}}"{{if .state}} class="{{.state}}"{{end}}{{if eq .state "now"}} aria-current="step"{{end}}>{{.label}}</li>{{end}}</ol></section>{{end}}
<div id="track" class="live"{{if ne .status "on_the_way"}} hidden{{end}}><div id="map"></div><p class="hint" id="seen" role="status">{{$.t.crew_coming}}</p></div>
<div class="order-grid"><section aria-labelledby="visit-h"><h2 id="visit-h">{{$.t.visit_details}}</h2>
<dl class="facts"><div><dt>{{$.t.address_short}}</dt><dd>{{.address}}{{if .flat}}, {{.flat}}{{end}}<span>{{.zone}}</span></dd></div>
{{with .crew}}<div><dt>{{$.t.crew}}</dt><dd>{{.}}</dd></div>{{end}}{{with .repeatText}}<div><dt>{{$.t.repeat}}</dt><dd>{{.}}</dd></div>{{end}}
{{with .notes}}<div><dt>{{$.t.notes}}</dt><dd>{{.}}</dd></div>{{end}}</dl>
{{if .photo}}<figure class="photo"><a href="{{.photo}}" target="_blank" rel="noopener"><img src="{{.photo}}" alt="{{$.t.photo}}"></a><figcaption class="hint">{{$.t.photo}}</figcaption></figure>{{end}}</section>
<aside class="sheet"><h2>{{$.t.price_title}}</h2><div class="rows">{{range .lines}}<div class="row"><span>{{.name}} × {{.qty}}</span><span>{{.amount}}</span></div>{{end}}
{{with .surcharge}}<div class="row"><span>{{$.t.area_fee}}</span><span>{{.}}</span></div>{{end}}
<div class="row total"><span>{{$.t.total}}</span><span>{{.total}}</span></div><div class="row sub"><span>{{$.t.vat_amount}}</span><span>{{.vat}}</span></div></div>
<p class="paid" id="payment">{{.paymentText}}</p>{{if .auto}}<p class="hint">{{$.t.auto_note}}</p>{{end}}{{with .refunded}}<p class="paid">{{$.t.refunded_amount}}: {{.}}</p>{{end}}
{{if .receipt}}<p class="small" style="margin-top:12px"><a href="/bookings/{{.id}}/receipt{{$.qs}}">{{$.t.view_receipt}}</a></p>{{end}}</aside></div>
{{if .canCancel}}<form class="cancel noprint" method="post" action="/bookings/{{.id}}/cancel{{$.qs}}"><h2>{{$.t.cancel_title}}</h2><p class="hint">{{$.cancelNote}}</p>
<div class="actions"><button class="btn line" name="later" value="0">{{$.t.cancel_visit}}</button>{{if .repeats}}<button class="btn line" name="later" value="1">{{$.t.cancel_series}}</button>{{end}}</div></form>{{end}}
<div class="actions noprint">{{if .again}}<a class="btn" href="/s/{{.serviceId}}{{$.qs}}">{{$.t.book_again}}</a>{{end}}<a class="btn line" href="/bookings{{$.qs}}">{{$.t.all_bookings}}</a></div></div>
{{if .live}}<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
var texts={{$.statusTexts}},start=[{{.lat}},{{.lng}}],has={{.hasPos}},map=null,marker=null,current={{.status}},STEPS=['confirmed','assigned','on_the_way','in_progress','completed'];
function showMap(){document.getElementById('track').hidden=false;if(map||!window.L)return;
 map=L.map('map').setView(has?start:[25.2048,55.2708],has?15:11);
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);
 if(has)marker=L.marker(start).addTo(map)}
// The tracker follows the status: earlier steps done, the current one marked.
function paintSteps(s){var at=STEPS.indexOf(s);document.querySelectorAll('#steps li').forEach(function(li,i){li.className=i<at?'done':i===at?'now':'';
 if(i===at)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')})}
if(current==='on_the_way')showMap();
// A change that alters the buttons (paid, cancelled, completed) reloads the page, once per status.
function again(s){try{if(sessionStorage.getItem('rx-booking-{{.id}}')===s)return;sessionStorage.setItem('rx-booking-{{.id}}',s)}catch(e){}live.close();location.reload()}
// The crew's page publishes every change to this booking's private channel.
var live=new EventSource('/_rx/live/{{$.channel}}?token='+encodeURIComponent({{$.token}}));
live.onmessage=function(e){var m=JSON.parse(e.data);
