    sel: {serviceId: sel.svc.id, service: pick(sel.svc, 'name', lang), zone: pick(sel.zone, 'name', lang), date: sel.date, dateText: fullDate(sel.date, t),
      slot: sel.slot, slotEnd: sel.slotEnd, repeatText: sel.repeat === 'once' ? '' : t['repeat_' + sel.repeat],
      lines: sel.q.lines.map(l => ({name: pick(l, 'name', lang), qty: l.qty, amount: price(l.price * l.qty, t)})),
