scripts.book:
// POST /book  form: service, qty, materials, zone, date, slot, repeat, name, phone, address, flat, notes, photo (an upload id),
// payment (card | cash | auto: card charged automatically for every repeat visit), lang
// The price, the area and the free window always come from the database, never from the browser.
function handle(req) {
  const f = req.form, b = biz();
  const lang = f.lang === 'ar' ? 'ar' : 'en', qa = lang === 'ar' ? '&lang=ar' : '';
  const sel = selection(f, b);
  if (sel.error) return {redirect: (sel.svc ? '/s/' + sel.svc.id : '/') + '?error=' + sel.error + qa};
  const back = '/s/' + sel.svc.id + '?error=';
  const name = (f.name || '').trim(), phone = (f.phone || '').trim(), address = (f.address || '').trim();
  const toCheckout = (error) => {
    const keep = ['service', 'qty', 'materials', 'zone', 'date', 'slot', 'repeat'].filter(k => f[k]).map(k => k + '=' + encodeURIComponent(f[k]));
    return {redirect: '/checkout?' + keep.join('&') + '&error=' + error + qa};
  };
  if (!name || !phone || !address) return toCheckout('error_fields');
  // The photo id comes from the browser: it must be a photo this visitor uploaded.
  let photo = null;
  if (f.photo) {
    const file = files.get(f.photo);
    if (!file || file.user_id !== req.user.id || file.type.indexOf('image/') !== 0) return toCheckout('error_photo');
    photo = file.id;
  }
  const auto = f.payment === 'auto' && !!b.card_enabled && sel.repeat !== 'once';
  let method = auto || (f.payment === 'card' && b.card_enabled) ? 'card' : 'cash';
  if (method === 'cash' && !b.cash_enabled) {
    if (!b.card_enabled) return {redirect: back + 'error_payment' + qa};
    method = 'card';
  }
  // Cash on completion is confirmed at once; a card booking waits for on_payment and holds its window meanwhile.
  const id = insertBooking({user_id: req.user.id, customer_name: name, phone: phone, email: req.user.email || '', zone_id: sel.zone.id, zone: sel.zone.name,
    address: address, flat: (f.flat || '').trim(), notes: (f.notes || '').trim().slice(0, 500), service_id: sel.svc.id, service: sel.svc.name,
    quantity: sel.q.qty, materials: sel.q.materials, date: sel.date, slot: sel.slot, slot_end: sel.slotEnd, repeat: sel.repeat, lines: sel.q.lines,
    subtotal: sel.q.subtotal, surcharge: sel.q.surcharge, vat: sel.q.vat, total: sel.q.total, payment_method: method,
    status: method === 'cash' ? 'confirmed' : 'pending', crew_id: null, lang: lang, parent_id: null, photo: photo, autopay: auto}, b);
  if (!id) return {redirect: back + 'error_slot' + qa};
  if (method === 'cash') {
    const bk = byId(id);
    emailCustomer(bk, 'confirm', req.origin + '/bookings/' + id);
    newBookingNotice(bk, req.origin);
    return {redirect: '/bookings/' + id + '?placed=1' + qa};
  }
  const items = sel.q.lines.map(l => ({name: l.name, price: l.price, quantity: l.qty}));
  if (sel.q.surcharge > 0) items.push({name: 'Area surcharge: ' + sel.zone.name, price: sel.q.surcharge, quantity: 1});
  const done = '/bookings/' + id + '?placed=1' + qa, cancel = '/bookings/' + id + (lang === 'ar' ? '?lang=ar' : '');
  try {
    let pay;
    if (auto) {
      // Every visit of the series is charged to the card: the first now, each later one by a renewal (see on_payment).
      const series = 'series-' + id;
      db.exec('UPDATE bookings SET series = ? WHERE id = ?', series, id);
      pay = payments.subscribe({items: items, interval: 'week', interval_count: sel.repeat === 'weekly' ? 1 : 2, reference: series,
        customer_email: req.user.email || '', success_path: done, cancel_path: cancel});
    } else {
      pay = payments.checkout({items: items, reference: 'booking-' + id, customer_email: req.user.email || '', success_path: done, cancel_path: cancel});
    }
    return {redirect: pay.url};
  } catch (e) {
    console.error('checkout failed for booking ' + id + ': ' + e);
    db.exec("UPDATE bookings SET status = 'failed' WHERE id = ?", id); // frees the window
    return {redirect: back + 'error_payment' + qa};
  }
}

