scripts.cancel:
// POST /bookings/:id/cancel  (signed in) form: later=1 also cancels the later visits of a repeating booking.
// Cancelling one visit keeps the repeats going; with later=1 the series stops (and its automatic payments).
// Visits paid by card are refunded to the card; when a refund cannot be made the owner is asked to do it.
function handle(req) {
  const lang = langOf(req), b = biz(), q = lang === 'ar' ? '?lang=ar' : '';
  const bk = db.query('SELECT * FROM bookings WHERE id = ? AND user_id = ?', Number(req.params.id), req.user.id)[0];
  if (!bk) return notFound(req);
  if (!canCancel(bk, b)) return {template: 'not_found', status: 409, data: page(req, {title: texts(lang).cancel_closed_title, heading: texts(lang).cancel_closed_title,
    message: texts(lang).error_cancel, back: '/bookings/' + bk.id + q})};
  const stop = req.form.later === '1';
  const cancelled = [bk];
  db.exec("UPDATE bookings SET status = 'cancelled', repeat_done = ? WHERE id = ?", stop || bk.repeat_done ? 1 : 0, bk.id);
  let last = bk.id;
  for (let i = 0; stop && i < 12; i++) {
    const next = db.query('SELECT * FROM bookings WHERE parent_id = ? AND user_id = ? ORDER BY id DESC LIMIT 1', last, req.user.id)[0];
    if (!next) break;
    if (['pending', 'confirmed', 'assigned'].indexOf(next.status) >= 0) {
      db.exec("UPDATE bookings SET status = 'cancelled', repeat_done = 1 WHERE id = ?", next.id);
      cancelled.push(next);
    } else db.exec('UPDATE bookings SET repeat_done = 1 WHERE id = ?', next.id);
    last = next.id;
  }
  if (stop && bk.series) {
    try { payments.cancel_subscription({reference: bk.series}); }
    catch (e) { console.warn('automatic payments of ' + bk.series + ' not stopped: ' + e); }
  }
  let refunded = 0, byHand = 0;
  const lines = [];
  for (const c of cancelled) {
    live(c.id, {status: 'cancelled'});
    let note = '';
    if (c.paid && c.payment_method === 'card') {
      const r = refundVisit(c, 'cancelled by the customer');
      if (r) { refunded += r; note = ' paid by card: refunded'; }
      else { byHand += c.total - (c.refunded || 0); note = ' paid by card: NOT refunded, refund it on the Payments page'; }
    }
    lines.push('#' + c.id + ' ' + c.date + ' ' + c.slot + ', AED ' + money(c.total) + note);
  }
  tellOwner('Booking #' + bk.id + ' cancelled by the customer: ' + bk.service + ', ' + bk.date + ' ' + bk.slot +
    (cancelled.length > 1 ? ' and ' + (cancelled.length - 1) + ' later' : '') + (refunded > 0 ? ', refunded AED ' + money(refunded) : '') +
    (byHand > 0 ? ', refund AED ' + money(byHand) + ' by hand' : ''),
    lines.join('\n') + (stop && bk.series ? '\nAutomatic card payments stopped.' : '') + '\n\nCustomer: ' + bk.customer_name + ', ' + bk.phone);
  return {redirect: '/bookings/' + bk.id + q};
}

