scripts.receipt:
// GET /bookings/:id/receipt  (signed in) printable receipt; a tax invoice once the business's TRN is set
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = biz();
  const bk = db.query('SELECT * FROM bookings WHERE id = ? AND user_id = ?', Number(req.params.id), req.user.id)[0];
  if (!bk || ['confirmed', 'assigned', 'on_the_way', 'in_progress', 'completed'].indexOf(bk.status) < 0) return notFound(req);
  const v = view(bk, lang, t);
  // Prices include 5% VAT: split each amount into net and VAT.
  const split = (gross) => { const net = round2(gross / 1.05); return {net: net, vat: round2(gross - net)}; };
  const rows = v.lines.map(l => ({name: l.name, qty: l.qty, unit: money(split(l.price).net), vat: money(split(l.price * l.qty).vat), total: money(l.price * l.qty)}));
  if (bk.surcharge > 0) { const s = split(bk.surcharge); rows.push({name: t.area_fee + ' (' + v.zone + ')', qty: 1, unit: money(s.net), vat: money(s.vat), total: money(bk.surcharge)}); }
  const totals = split(bk.total);
  const title = b.trn ? t.tax_invoice : t.receipt;
  return {template: 'receipt', data: page(req, {title: title, r: {id: bk.id, title: title, issued: longDate(bk.created_at, t), visit: v.dateText,
    window: bk.slot + '–' + bk.slot_end, service: v.service,
    seller: pick(b, 'legal_name', lang) || pick(b, 'name', lang), sellerAddress: pick(b, 'address', lang) || '', trn: b.trn || '', buyer: bk.customer_name,
    buyerAddress: bk.address + (bk.flat ? ', ' + bk.flat : '') + (lang === 'ar' ? '، ' : ', ') + v.zone, phone: bk.phone, rows: rows,
    net: price(totals.net, t), vat: price(totals.vat, t), total: price(bk.total, t), payment: v.paymentText}})};
}

