    timezone: 'Asia/Dubai', bookable_days_ahead: b.days_ahead, minimum_order: b.min_order || 0, free_cancellation_hours_before: b.cancel_hours || 0,
    payment_methods: [b.card_enabled ? 'card' : null, b.cash_enabled ? 'cash on completion' : null].filter(Boolean),
