scripts.admin_change:
// on_admin_change: runs right after the owner or staff adds or changes a booking in the admin panel.
// - A crew is set or changed (or the status set to assigned with a crew): the booking becomes assigned, the customer is
//   emailed the crew's first name and their open booking page updates.
// - Cancelled: a card payment is refunded and the customer is emailed.
// - Any other status change (on the way, completed...) reaches the customer's open booking page at once.
// Every booking gets a crew key if it has none.
function handle(req) {
  const c = req.body;
  if (c.table !== 'bookings' || !c.row) return {text: 'nothing to do'};
  const was = c.before || {}, id = c.row.id, done = [];
  if (!c.row.crew_key) {
    db.exec('UPDATE bookings SET crew_key = ? WHERE id = ?', newKey(), id);
    done.push('crew key made');
  }
  let bk = byId(id);
  const link = req.origin + '/bookings/' + id;
  if (bk.status === 'cancelled' && was.status !== 'cancelled') {
    const due = bk.paid && bk.payment_method === 'card' ? round2(bk.total - (bk.refunded || 0)) : 0;
    const refund = refundVisit(bk, 'cancelled by the business');
    if (due > 0 && !refund) {
      tellOwner('Refund NOT made for cancelled booking #' + id + ': AED ' + money(due), 'Refund it on the Payments page.\n' + bk.customer_name + ', ' + bk.phone);
    }
    emailCustomer(byId(id), 'cancelled', link, (t) => ({refund: refund ? t.email_refund_line.replace(/\{amount\}/g, price(refund, t)) : ''}));
    live(id, {status: 'cancelled'});
    done.push('cancelled' + (refund ? ', refunded AED ' + money(refund) : '') + ', customer emailed');
    return {text: done.join('; ')};
  }
  const crewSet = !!bk.crew_id && bk.crew_id !== was.crew_id;
  const toAssigned = bk.status === 'assigned' && was.status !== 'assigned';
  const crew = bk.crew_id ? db.query('SELECT name FROM crews WHERE id = ?', bk.crew_id)[0] : null;
  if ((crewSet || toAssigned) && crew && (bk.status === 'confirmed' || bk.status === 'assigned')) {
    if (bk.status === 'confirmed') db.exec("UPDATE bookings SET status = 'assigned' WHERE id = ?", id);
    bk = byId(id);
    emailCustomer(bk, 'assigned', link, {crew: String(crew.name).trim().split(/\s+/)[0]});
    done.push('crew ' + crew.name + ' assigned, customer emailed, crew link ' + req.origin + '/crew/' + id + '?key=' + bk.crew_key);
  }
  if (bk.status !== was.status) {
    live(id, {status: bk.status});
    done.push('status ' + bk.status + ' sent to the booking page');
  }
  return {text: done.join('; ') || 'nothing to do'};
}

lib.common:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
const textCache = {};
function texts(lang) {
  if (textCache[lang]) return textCache[lang];
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return textCache[lang] = t;
}
let bizRow = null;
function biz() { return bizRow || (bizRow = db.query('SELECT * FROM business ORDER BY id LIMIT 1')[0]); }
function money(n) { return (Math.round((n || 0) * 100) / 100).toFixed(2); }
function round2(n) { return Math.round(n * 100) / 100; }
// An amount with its currency in the page's language, from texts.money: "AED 250.00" or "250.00 د.إ".
function price(n, t) { return (t.money || 'AED {n}').replace('{n}', money(n)); }
// The same for notes and sentences: whole amounts without decimals ("AED 15"), kept on one line.
function amount(n, t) { const v = Math.round((n || 0) * 100) / 100; return (t.money || 'AED {n}').replace('{n}', v % 1 === 0 ? String(v) : v.toFixed(2)).replace(/ /g, ' '); }
// 'YYYY-MM-DD' as "19 Nov 2026" or "19 نوفمبر 2026" (month names from texts.months, Western digits).
function longDate(ymd, t) {
  const p = String(ymd || '').slice(0, 10).split('-'), m = String(t.months || '').split('|');
  if (p.length !== 3 || m.length !== 12) return String(ymd || '');
  return Number(p[2]) + ' ' + m[Number(p[1]) - 1] + ' ' + p[0];
}
// The weekday in front: "Thu 19 Nov 2026" / "الخميس 19 نوفمبر 2026" (texts.weekdays, Sunday first).
// short leaves out the year, for the date picker.
function fullDate(ymd, t, short) {
  const w = String(t.weekdays || '').split('|'), ms = Date.parse(String(ymd).slice(0, 10) + 'T00:00:00Z');
  const d = short ? longDate(ymd, t).replace(/ \d{4}$/, '') : longDate(ymd, t);
  return isNaN(ms) || w.length !== 7 ? d : w[new Date(ms).getUTCDay()] + ' ' + d;
}
// The Arabic value of a column when the page is Arabic and it is filled in.
function pick(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }
// UAE time is UTC+4 all year. Dates and times are kept as local text: 'YYYY-MM-DD' and 'HH:MM'.
function dubaiNow() { const d = new Date(Date.now() + 4 * 3600 * 1000).toISOString(); return {date: d.slice(0, 10), time: d.slice(11, 16)}; }
function addDays(date, n) { return new Date(Date.parse(date + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10); }
// The current address in the other language, keeping the other query parameters (service, crew key) but not a message.
function langLink(req, lang) {
  const q = [];
  for (const k in req.query) if (k !== 'lang' && k !== 'error' && k !== 'placed') q.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  if (lang === 'ar') q.push('lang=ar');
  return req.path + (q.length ? '?' + q.join('&') : '');
}
// "Visits 08:00–20:00, closed on Sundays": the first arrival to the end of the last window.
function hoursNote(b, t) {
  const end = clock(minutes(b.last_slot) + Math.max(30, (b.slot_hours || 2) * 60));
  const days = String(t.weekdays_plural || '').split('|'), closed = WEEKDAYS.indexOf(b.closed_weekday);
  const s = closed >= 0 && days.length === 7 ? t.hours_closed.replace('{day}', days[closed]) : t.hours;
  return s.replace('{first}', b.first_slot).replace('{last}', end);
}
function page(req, extra) {
  const lang = langOf(req), b = biz(), t = texts(lang);
  const rest = Object.keys(req.query).filter(k => k !== 'lang' && k !== 'error' && k !== 'placed')
    .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  const here = rest.concat(lang === 'ar' ? ['lang=ar'] : []);
  const qs = lang === 'ar' ? '?lang=ar' : '';
  const name = pick(b, 'name', lang);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', t: t, user: req.user, biz: b, theme: theme(b),
    bizName: name, storeName: name, tagline: pick(b, 'tagline', lang), story: pick(b, 'story', lang) || '', address: pick(b, 'address', lang) || '',
    qs: qs, amp: lang === 'ar' ? '&lang=ar' : '', here: req.path + (here.length ? '?' + here.join('&') : ''),
    langEn: langLink(req, 'en'), langAr: langLink(req, 'ar'), wa: (b.whatsapp || '').replace(/[^0-9]/g, ''), hoursNote: hoursNote(b, t)};
  for (const k in extra) base[k] = extra[k];
  return base;
}
// The message of an ?error=key redirect.
function errorText(key, t, b) { return key && t[key] ? t[key].replace(/\{min\}/g, amount(b.min_order || 0, t)) : ''; }
function notFound(req) { return {template: 'not_found', status: 404, data: page(req, {title: texts(langOf(req)).not_found_title})}; }
// Tells the customer's open booking page at once; never fails the request.
function live(id, data) {
  try { realtime.publish({channel: 'booking-' + id, data: data}); } catch (e) { console.warn('live update not sent: ' + e); }
}

lib.theme:
// Merchant branding from the settings row (brand_color, font, logo), shared by every Renoxium template.
// theme(row) returns {brand, onBrand, brandText, font, style, lux, logo}; the "top" template puts them on <html>
// (data-font, data-style and CSS variables).
// brand: the owner's colour (#rrggbb); when it is empty or not a colour, a quiet slate (or a deep ink for the luxury styles).
// onBrand: white or near-black, whichever reads better on brand (buttons, the intro band).
// brandText: brand darkened until it passes WCAG AA (4.5:1) as text on white, for links and selected states.
// font picks the type pair and the style:
//   modern (IBM Plex Sans + IBM Plex Sans Arabic), classic (Markazi Text headings + IBM Plex), rounded (Rubik): style "standard".
//   heritage (Cormorant Garamond + Jost, Amiri + Noto Naskh Arabic; ivory, antique gold hairlines) and
//   atelier (Bodoni Moda + Hanken Grotesk, Noto Naskh Arabic + Noto Kufi Arabic; white, near monochrome): style "luxury",
//   which switches to the luxury layout (centred name, full-bleed photo, no boxes, square buttons).
const THEME_DEFAULT_BRAND = '#334155';
const THEME_DEFAULT_INK = '#1f1b17';
const THEME_FONTS = ['modern', 'classic', 'rounded', 'heritage', 'atelier'];
const THEME_LUXURY = ['heritage', 'atelier'];
function themeHex(v) {
  let s = String(v || '').trim().toLowerCase();
  if (/^#?[0-9a-f]{3}$/.test(s)) s = s.replace('#', '').split('').map(c => c + c).join('');
  s = s.replace('#', '');
  return /^[0-9a-f]{6}$/.test(s) ? '#' + s : '';
}
function themeRgb(hex) { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
function themeLum(rgb) {
  const c = rgb.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function themeContrast(a, b) { const x = themeLum(a), y = themeLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function themeToHex(rgb) { return '#' + rgb.map(v => (Math.round(v) < 16 ? '0' : '') + Math.round(v).toString(16)).join(''); }
function theme(row) {
  row = row || {};
  const font = THEME_FONTS.indexOf(row.font) >= 0 ? row.font : 'modern';
  const lux = THEME_LUXURY.indexOf(font) >= 0;
  const brand = themeHex(row.brand_color) || (lux ? THEME_DEFAULT_INK : THEME_DEFAULT_BRAND);
  const rgb = themeRgb(brand), white = [255, 255, 255], ink = [26, 23, 22];
  const onBrand = themeContrast(rgb, white) >= themeContrast(rgb, ink) ? '#ffffff' : '#1a1716';
  let text = rgb;
  for (let i = 0; i < 20 && themeContrast(text, white) < 4.5; i++) text = text.map(v => v * 0.9);
  return {brand: brand, onBrand: onBrand, brandText: themeToHex(text), font: font, style: lux ? 'luxury' : 'standard', lux: lux, logo: row.logo || ''};
}

lib.dates:
const WEEKDAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
function pad(n) { return (n < 10 ? '0' : '') + n; }
function minutes(hhmm) { const p = String(hhmm || '').split(':'); return Number(p[0]) * 60 + Number(p[1] || 0); }
function clock(m) { return pad(Math.floor(m / 60)) + ':' + pad(m % 60); }
// Why a date cannot be booked, or '' when it can.
function dateProblem(date, b) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'not a date (use YYYY-MM-DD)';
  const ms = Date.parse(date + 'T00:00:00Z');
  if (isNaN(ms) || new Date(ms).toISOString().slice(0, 10) !== date) return 'not a date (use YYYY-MM-DD)';
  const today = dubaiNow().date;
  if (date < today) return 'in the past';
  if (date > addDays(today, b.days_ahead || 14)) return 'too far ahead';
  if (WEEKDAYS[new Date(ms).getUTCDay()] === b.closed_weekday) return 'closed on this weekday';
  return '';
}
// The arrival windows of a date, each with the number of crews still free.
// A booking holds its window unless it was cancelled, refunded, or its card payment failed or expired.
function slotsOf(date, b) {
  if (dateProblem(date, b)) return [];
  const taken = {};
  for (const r of db.query(`SELECT slot, COUNT(*) AS n FROM bookings WHERE date = ? AND status NOT IN ('cancelled', 'failed', 'expired', 'refunded') GROUP BY slot`, date)) taken[r.slot] = r.n;
  const now = dubaiNow(), step = Math.max(30, (b.slot_hours || 2) * 60), out = [];
  for (let m = minutes(b.first_slot); m <= minutes(b.last_slot) && out.length < 48; m += step) {
    const start = clock(m);
    const tooSoon = date === now.date && m < minutes(now.time) + 120; // today, a crew needs two hours' notice
    out.push({start: start, end: clock(m + step), left: tooSoon ? 0 : Math.max(0, (b.crews_per_slot || 1) - (taken[start] || 0))});
  }
  return out;
}
function bookableDates(b) {
  const out = [], today = dubaiNow().date;
  for (let i = 0; i <= (b.days_ahead || 14) && i < 60; i++) { const d = addDays(today, i); if (!dateProblem(d, b)) out.push(d); }
  return out;
}

lib.pricing:
// The price of a visit, always from the database. Prices include 5% VAT, so vat = total * 5 / 105.
function quote(svc, quantity, zone, materials, b) {
  const qty = svc.unit === 'fixed' ? 1 : Math.floor(Number(quantity));
  if (!(qty >= (svc.min_qty || 1) && qty <= (svc.max_qty || 99))) return {error: 'error_quantity'};
  const lines = [{name: svc.name, name_ar: svc.name_ar || '', price: svc.price, qty: qty}];
  if (materials && svc.materials_price > 0) {
    lines.push({name: texts('en').materials, name_ar: texts('ar').materials, price: svc.materials_price, qty: svc.unit === 'per_hour' ? qty : 1});
  }
  let subtotal = 0;
  for (const l of lines) subtotal += l.price * l.qty;
  subtotal = round2(subtotal);
  if (subtotal < (b.min_order || 0)) return {error: 'error_minimum'};
  const surcharge = zone.surcharge || 0, total = round2(subtotal + surcharge);
  return {qty: qty, lines: lines, materials: lines.length > 1, subtotal: subtotal, surcharge: surcharge, total: total, vat: round2(total * 5 / 105)};
}
// What the visitor chose (service, qty, materials, zone, date, slot, repeat), checked against the database.
function selection(src, b) {
  const svc = db.query('SELECT * FROM services WHERE id = ? AND active = 1', Number(src.service))[0];
  if (!svc) return {error: 'error_service'};
  const zone = db.query('SELECT * FROM zones WHERE id = ? AND active = 1', Number(src.zone))[0];
  if (!zone) return {error: 'error_zone', svc: svc};
  const q = quote(svc, src.qty, zone, src.materials === '1', b);
  if (q.error) return {error: q.error, svc: svc};
  const slot = slotsOf(src.date || '', b).find(s => s.start === src.slot);
  if (!slot || slot.left < 1) return {error: 'error_slot', svc: svc};
  return {svc: svc, zone: zone, q: q, date: src.date, slot: slot.start, slotEnd: slot.end,
    repeat: src.repeat === 'weekly' || src.repeat === 'every_2_weeks' ? src.repeat : 'once'};
}
// A service as the pages show it, with its prices in words from the texts: "AED 40.00", "per hour", "+ AED 10.00 per hour".
function serviceView(s, lang) {
  const t = texts(lang), unitLabel = s.unit === 'fixed' ? '' : (pick(s, 'unit_label', lang) || '');
  const per = s.unit === 'fixed' ? t.per_visit : t.per.replace('{unit}', unitLabel);
  return {id: s.id, name: pick(s, 'name', lang), description: pick(s, 'description', lang) || '', category: pick(s, 'category', lang) || '',
    price: money(s.price), priceText: price(s.price, t), perText: per, fixed: s.unit === 'fixed', hourly: s.unit === 'per_hour', unitLabel: unitLabel,
    min: s.unit === 'fixed' ? 1 : (s.min_qty || 1), max: s.unit === 'fixed' ? 1 : (s.max_qty || 99),
    materials: s.materials_price > 0 ? money(s.materials_price) : '',
    materialsText: s.materials_price > 0 ? price(s.materials_price, t) + ' ' + (s.unit === 'per_hour' ? per : t.per_visit) : '', image: s.image || ''};
}
function zoneViews(lang) {
  const t = texts(lang);
  return db.query('SELECT * FROM zones WHERE active = 1 ORDER BY id').map(z => ({id: z.id, name: pick(z, 'name', lang),
    surcharge: z.surcharge > 0 ? price(z.surcharge, t) : '', surchargeShort: z.surcharge > 0 ? amount(z.surcharge, t) : '', surchargeNum: z.surcharge || 0}));
}

lib.visits:
// A secret for the crew link: anyone with /crew/<id>?key=<key> sees the job and changes its status.
function newKey() { return crypto.randomId(); }

// Inserts the booking only while its arrival window still has a free crew (one statement, so two visitors
// cannot take the last place together). v needs every column below except photo, autopay and series.
// Returns the new id, or 0 when full.
function insertBooking(v, b) {
  const r = db.exec(`INSERT INTO bookings (user_id, customer_name, phone, email, zone_id, zone, address, flat, notes, service_id, service, quantity, materials,
      date, slot, slot_end, repeat, lines, subtotal, surcharge, vat, total, payment_method, status, paid, crew_id, crew_key, lang, parent_id, photo, autopay, series)
    SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?, ?
    WHERE (SELECT COUNT(*) FROM bookings WHERE date = ? AND slot = ? AND status NOT IN ('cancelled', 'failed', 'expired', 'refunded')) < ?`,
    v.user_id, v.customer_name, v.phone, v.email, v.zone_id, v.zone, v.address, v.flat, v.notes, v.service_id, v.service, v.quantity, v.materials,
    v.date, v.slot, v.slot_end, v.repeat, JSON.stringify(v.lines), v.subtotal, v.surcharge, v.vat, v.total, v.payment_method, v.status,
    v.crew_id, newKey(), v.lang, v.parent_id, v.photo || null, v.autopay ? 1 : 0, v.series || null, v.date, v.slot, b.crews_per_slot || 1);
  return r.rowsAffected ? r.lastInsertId : 0;
}

function byId(id) { return db.query('SELECT * FROM bookings WHERE id = ?', id)[0] || null; }

// Books the visit after p (weekly or every 2 weeks, same window) and marks p as handled, so this happens once
// whether the daily job or an automatic payment gets there first. A visit of an automatic-payment series keeps
// the price the customer subscribed to and waits for its card charge (autopay); other visits are paid on completion.
// Returns {id, date} or {date, problem}.
function bookNext(p, b) {
  const next = addDays(p.date, p.repeat === 'weekly' ? 7 : 14);
  db.exec('UPDATE bookings SET repeat_done = 1 WHERE id = ?', p.id);
  const sel = selection({service: String(p.service_id), zone: String(p.zone_id), qty: String(p.quantity), materials: p.materials ? '1' : '',
    date: next, slot: p.slot, repeat: p.repeat}, b);
  if (sel.error) return {date: next, problem: sel.error === 'error_slot' ? 'window full or day closed' : sel.error.replace('error_', '') + ' no longer available'};
  const auto = !!p.series;
  const q = auto ? {qty: p.quantity, lines: JSON.parse(p.lines), materials: p.materials, subtotal: p.subtotal, surcharge: p.surcharge, vat: p.vat, total: p.total} : sel.q;
  const id = insertBooking({user_id: p.user_id, customer_name: p.customer_name, phone: p.phone, email: p.email, zone_id: sel.zone.id, zone: sel.zone.name,
    address: p.address, flat: p.flat, notes: p.notes, service_id: sel.svc.id, service: sel.svc.name, quantity: q.qty, materials: q.materials,
    date: next, slot: sel.slot, slot_end: sel.slotEnd, repeat: p.repeat, lines: q.lines, subtotal: q.subtotal, surcharge: q.surcharge,
    vat: q.vat, total: q.total, payment_method: auto ? 'card' : 'cash', status: p.crew_id ? 'assigned' : 'confirmed', crew_id: p.crew_id, lang: p.lang,
    parent_id: p.id, autopay: auto, series: p.series}, b);
  return id ? {id: id, date: next} : {date: next, problem: 'window full or day closed'};
}

// The upcoming visit of a series that an automatic payment is for: the first one not paid yet, or else the next
// visit, booked now. Returns {bk, created} or null when there is none and none can be booked.
function seriesVisit(series, b) {
  const open = db.query(`SELECT * FROM bookings WHERE series = ? AND paid = 0 AND status IN ('confirmed', 'assigned') ORDER BY date, id LIMIT 1`, series)[0];
  if (open) return {bk: open, created: false};
  const last = db.query(`SELECT * FROM bookings WHERE series = ? AND coalesce(repeat_done, 0) = 0
    AND status IN ('confirmed', 'assigned', 'on_the_way', 'in_progress', 'completed', 'cancelled') ORDER BY date DESC, id DESC LIMIT 1`, series)[0];
  if (!last) return null;
  const n = bookNext(last, b);
  if (!n.id) { console.warn('series ' + series + ': next visit ' + n.date + ' not booked: ' + n.problem); return null; }
  return {bk: byId(n.id), created: true};
}

// Refunds what is left of a card-paid visit to the card that paid it (its own payment, or the automatic payment
// of its series). Returns the amount refunded, or 0 when nothing was refunded (the reason is in the log).
function refundVisit(bk, reason) {
  const amount = round2(bk.total - (bk.refunded || 0));
  if (!bk.paid || bk.payment_method !== 'card' || amount <= 0) return 0;
  try {
    payments.refund({reference: bk.pay_ref || 'booking-' + bk.id, amount: amount, reason: reason});
  } catch (e) {
    console.warn('refund of booking ' + bk.id + ' not made: ' + e);
    return 0;
  }
  db.exec('UPDATE bookings SET refunded = ? WHERE id = ?', round2((bk.refunded || 0) + amount), bk.id);
  return amount;
}

function paymentText(bk, t) {
  if (bk.paid) return bk.payment_method === 'card' ? t.paid_card : t.paid_cash;
  if (bk.autopay) return t.pay_auto;
  return bk.payment_method === 'card' ? t.pay_card : t.pay_cash;
}

// Emails the customer in the booking's language: kind is confirm, reminder, repeat, repeat_auto, payment_failed,
// assigned or cancelled (texts email_<kind>_subject and _body). more: {placeholder: value}, or a function of the
// texts returning that. Formatted as on the booking page: {date} "Thu 19 Nov 2026" / "الخميس 19 نوفمبر 2026",
// {slot} the arrival window (texts.email_window), {total} "AED 250.00" / "250.00 د.إ"; link gets ?lang=ar for Arabic.
// Quiet on failure.
function emailCustomer(bk, kind, link, more) {
  if (!bk.email) return;
  const lang = bk.lang === 'ar' ? 'ar' : 'en', t = texts(lang), b = biz();
  const line = JSON.parse(bk.lines || '[]')[0] || {};
  const zone = db.query('SELECT name, name_ar FROM zones WHERE id = ?', bk.zone_id)[0];
  const extra = typeof more === 'function' ? more(t) : more || {};
  const vals = {id: bk.id, business: pick(b, 'name', lang), service: pick(line, 'name', lang) || bk.service, date: fullDate(bk.date, t),
    slot: String(t.email_window).replace('{start}', bk.slot).replace('{end}', bk.slot_end),
    address: bk.address + (bk.flat ? ', ' + bk.flat : '') + ', ' + (zone ? pick(zone, 'name', lang) : bk.zone), total: price(bk.total, t),
    payment: paymentText(bk, t), link: link + (lang === 'ar' ? '?lang=ar' : '')};
  for (const k in extra) vals[k] = extra[k];
  const fill = (s) => String(s || '').replace(/\{(\w+)\}/g, (m, k) => vals[k] === undefined ? m : String(vals[k]));
  try { email.send({to: bk.email, subject: fill(t['email_' + kind + '_subject']), text: fill(t['email_' + kind + '_body'])}); }
  catch (e) { console.warn(kind + ' email not sent for booking ' + bk.id + ': ' + e); }
}

// The owner gets an email, and the subject on WhatsApp if they turned that on: keep the essentials in it.
function tellOwner(subject, text) {
  try { notify.owner({subject: subject.slice(0, 150), text: text}); } catch (e) { console.warn('owner not notified: ' + e); }
}

function jobText(bk, origin) {
  return bk.service + ' x ' + bk.quantity + (bk.materials ? ' (with materials)' : '') + '\n' + bk.date + ', arrival ' + bk.slot + ' - ' + bk.slot_end +
    (bk.repeat !== 'once' ? ' (' + bk.repeat.replace(/_/g, ' ') + (bk.series ? ', paid automatically by card' : '') + ')' : '') +
    '\n\nCustomer: ' + bk.customer_name + ', ' + bk.phone +
    '\nAddress: ' + bk.address + (bk.flat ? ', ' + bk.flat : '') + ', ' + bk.zone + (bk.notes ? '\nNotes: ' + bk.notes : '') +
    (bk.photo ? '\nPhoto of the problem: attached, open booking #' + bk.id + ' in the admin panel to see it' : '') +
    '\nTotal: AED ' + money(bk.total) + (bk.paid ? ' (paid)' : ' (to collect)') +
    '\n\nSet the crew in the admin panel (the customer is emailed), then send the crew this link:\n' + origin + '/crew/' + bk.id + '?key=' + bk.crew_key;
}

function newBookingNotice(bk, origin) {
  tellOwner('New booking #' + bk.id + ' (' + (bk.paid ? 'card, paid' : 'cash') + '): ' + bk.service + ', ' + bk.date + ' ' + bk.slot + ', ' + bk.zone +
    ', AED ' + money(bk.total) + (bk.photo ? ', photo attached' : ''), jobText(bk, origin));
}

// Customers can cancel while no crew has set off and the cut-off before the arrival window has not passed.
function canCancel(bk, b) {
  if (['pending', 'confirmed', 'assigned'].indexOf(bk.status) < 0) return false;
  const starts = Date.parse(bk.date + 'T' + bk.slot + ':00Z') - 4 * 3600 * 1000;
  return Date.now() + (b.cancel_hours || 0) * 3600 * 1000 <= starts;
}

// A visit waiting for its automatic card charge is never paid by hand as well.
function canPay(bk, b) {
  if (bk.autopay && !bk.paid) return false;
  if (bk.status === 'pending') return true;
  return !bk.paid && !!b.card_enabled && (bk.status === 'confirmed' || bk.status === 'assigned');
}

// A booking as the templates show it: amounts with their currency, the date in words.
function view(bk, lang, t) {
  const lines = JSON.parse(bk.lines || '[]').map(l => ({name: pick(l, 'name', lang), qty: l.qty, price: l.price, amount: price(l.price * l.qty, t)}));
  const zone = db.query('SELECT name, name_ar FROM zones WHERE id = ?', bk.zone_id)[0];
  return {id: bk.id, title: t.booking_no.replace('{id}', bk.id), status: bk.status, statusText: t['status_' + bk.status] || bk.status,
    service: lines.length ? lines[0].name : bk.service, serviceId: bk.service_id,
    quantity: bk.quantity, date: bk.date, dateText: fullDate(bk.date, t), slot: bk.slot, slotEnd: bk.slot_end,
    zone: zone ? pick(zone, 'name', lang) : bk.zone, address: bk.address, flat: bk.flat || '',
    notes: bk.notes || '', name: bk.customer_name, phone: bk.phone, lines: lines, surcharge: bk.surcharge > 0 ? price(bk.surcharge, t) : '', vat: price(bk.vat, t),
    total: price(bk.total, t), repeats: bk.repeat !== 'once', repeatText: bk.repeat === 'once' ? '' : t['repeat_' + bk.repeat],
    auto: !!bk.series, refunded: bk.refunded > 0 ? price(bk.refunded, t) : '', paymentText: paymentText(bk, t)};
}

// The steps of a visit, for the tracker on the booking and crew pages: done, now (the current one) or still to come.
const STEPS = ['confirmed', 'assigned', 'on_the_way', 'in_progress', 'completed'];
function steps(status, t) {
  const at = STEPS.indexOf(status);
  if (at < 0) return [];
  return STEPS.map((s, i) => ({key: s, label: t['status_' + s] || s, state: i < at || status === 'completed' ? 'done' : i === at ? 'now' : ''}));
}

// The crew's name for the customer: "Imran Khan (AC and handyman)" shows as "Imran Khan".
function crewName(name) { return String(name || '').replace(/\s*\(.*\)\s*$/, ''); }

function statusTexts(t) {
  const m = {};
  for (const k in t) if (k.indexOf('status_') === 0) m[k.slice(7)] = t[k];
  return m;
}

// The crew's link carries the booking's secret key; without it there is no job.
function jobFor(req, key) {
  const bk = db.query('SELECT * FROM bookings WHERE id = ?', Number(req.params.id))[0];
  return bk && key && bk.crew_key === key ? bk : null;
}
